import java.util.*;

public List<Integer> firstPrimesTrial(int q) {
    List<Integer> primes = new ArrayList<>();
    int cand = 2;
    while (primes.size() < q) {
        boolean isPrime = true;
        for (int p : primes) {
            if ((long) p * p > cand) break;
            if (cand % p == 0) { isPrime = false; break; }
        }
        if (isPrime) primes.add(cand);
        cand++;
    }
    return primes;
}

public List<Integer> waiter(int[] number, int q) {
    List<Integer> primes = firstPrimesTrial(q);
    List<Integer> answer = new ArrayList<>();
    List<Integer> cur = new ArrayList<>();
    for (int x : number) cur.add(x);
    for (int i = 0; i < q; i++) {
        int p = primes.get(i);
        List<Integer> a = new ArrayList<>();
        List<Integer> b = new ArrayList<>();
        for (int plate : cur) {
            if (plate % p == 0) b.add(plate);
            else a.add(plate);
        }
        for (int j = b.size() - 1; j >= 0; j--) answer.add(b.get(j));
        cur = a;
    }
    for (int j = cur.size() - 1; j >= 0; j--) answer.add(cur.get(j));
    return answer;
}

