import java.util.*;

public List<Integer> firstPrimes(int q) {
    int limit = 100000;            // safely above the q-th prime for the constraints
    boolean[] composite = new boolean[limit + 1];
    List<Integer> primes = new ArrayList<>();
    for (int i = 2; i <= limit && primes.size() < q; i++) {
        if (!composite[i]) {
            primes.add(i);
            for (long j = (long) i * i; j <= limit; j += i) {
                composite[(int) j] = true;
            }
        }
    }
    return primes;
}

public List<Integer> waiter(int[] number, int q) {
    List<Integer> primes = firstPrimes(q);
    List<Integer> answer = new ArrayList<>();
    List<Integer> cur = new ArrayList<>();
    for (int x : number) cur.add(x);
    for (int i = 0; i < q; i++) {
        int p = primes.get(i);
        List<Integer> a = new ArrayList<>();
        List<Integer> b = new ArrayList<>();
        for (int plate : cur) {
            if (plate % p == 0) b.add(plate);
            else a.add(plate);
        }
        for (int j = b.size() - 1; j >= 0; j--) answer.add(b.get(j));
        cur = a;
    }
    for (int j = cur.size() - 1; j >= 0; j--) answer.add(cur.get(j));
    return answer;
}

