def first_primes(self, q: int) -> list[int]:
    limit = 100000  # safely above the q-th prime for the constraints
    composite = [False] * (limit + 1)
    primes: list[int] = []
    i = 2
    while i <= limit and len(primes) < q:
        if not composite[i]:
            primes.append(i)
            for j in range(i * i, limit + 1, i):
                composite[j] = True
        i += 1
    return primes

def waiter(self, number: list[int], q: int) -> list[int]:
    primes = self.first_primes(q)
    answer: list[int] = []
    cur = list(number)
    for i in range(q):
        p = primes[i]
        a: list[int] = []
        b: list[int] = []
        for plate in cur:
            if plate % p == 0:
                b.append(plate)
            else:
                a.append(plate)
        while b:
            answer.append(b.pop())
        cur = a
    while cur:
        answer.append(cur.pop())
    return answer

